"""Adjusts the Android files generated by `flutter create`:
app name, application id, location permissions, and SMS/phone intents."""
import os
import re
import pathlib

APP_ID = "mr.amane.securite"

manifest = pathlib.Path("android/app/src/main/AndroidManifest.xml")
s = manifest.read_text(encoding="utf-8")

perms = (
    '    <uses-permission android:name="android.permission.INTERNET"/>\n'
    '    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/>\n'
    '    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>\n'
    '    <uses-permission android:name="android.permission.FOREGROUND_SERVICE"/>\n'
    '    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_LOCATION"/>\n'
    '    <uses-permission android:name="android.permission.WAKE_LOCK"/>\n'
    '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>\n'
)
if "ACCESS_FINE_LOCATION" not in s:
    s = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + perms, s, count=1)

s = re.sub(r'android:label="[^"]*"', 'android:label="Amane"', s, count=1)

queries = (
    "    <queries>\n"
    '        <intent><action android:name="android.intent.action.SENDTO"/><data android:scheme="sms"/></intent>\n'
    '        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="sms"/></intent>\n'
    '        <intent><action android:name="android.intent.action.DIAL"/><data android:scheme="tel"/></intent>\n'
    '        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>\n'
    "    </queries>\n"
)
if 'android:scheme="sms"' not in s:
    s = s.replace("</manifest>", queries + "</manifest>")
manifest.write_text(s, encoding="utf-8")

for name in ("android/app/build.gradle.kts", "android/app/build.gradle"):
    g = pathlib.Path(name)
    if g.exists():
        t = g.read_text(encoding="utf-8")
        t = re.sub(r'applicationId\s*=?\s*"[^"]*"', f'applicationId = "{APP_ID}"', t, count=1)
        # Clé de signature permanente (mot de passe dans le secret GitHub AMANE_KEY_PASSWORD).
        # Sans le secret, Flutter signe avec une clé de test qui change à chaque build.
        if os.environ.get("AMANE_KEY_PASSWORD") and name.endswith(".kts") and "amane-upload" not in t:
            block = (
                '    signingConfigs {\n'
                '        create("release") {\n'
                '            storeFile = file("../../keys/amane-upload.p12")\n'
                '            storePassword = System.getenv("AMANE_KEY_PASSWORD")\n'
                '            keyAlias = "amane"\n'
                '            keyPassword = System.getenv("AMANE_KEY_PASSWORD")\n'
                '            storeType = "pkcs12"\n'
                '        }\n'
                '    }\n\n'
            )
            t = t.replace("    buildTypes {", block + "    buildTypes {", 1)
            t = t.replace('signingConfig = signingConfigs.getByName("debug")',
                          'signingConfig = signingConfigs.getByName("release")')
            print("Release signing: permanent AMANE key")
        # Firebase demande Android 6 (API 23) au minimum.
        if name.endswith(".kts"):
            t = t.replace("minSdk = flutter.minSdkVersion", "minSdk = maxOf(23, flutter.minSdkVersion)")
        else:
            t = t.replace("minSdk = flutter.minSdkVersion", "minSdk = Math.max(23, flutter.minSdkVersion)")
            t = t.replace("minSdkVersion flutter.minSdkVersion", "minSdkVersion Math.max(23, flutter.minSdkVersion)")
        g.write_text(t, encoding="utf-8")

# Sirène SOS : son personnalisé + canal de notification « sos_siren » (importance
# haute, flux ALARME pour sonner même en mode vibreur).
import shutil
raw = pathlib.Path("android/app/src/main/res/raw")
raw.mkdir(parents=True, exist_ok=True)
shutil.copy("assets/siren.wav", raw / "siren.wav")
(raw / "keep.xml").write_text(
    '<?xml version="1.0" encoding="utf-8"?>\n'
    '<resources xmlns:tools="http://schemas.android.com/tools" tools:keep="@raw/siren"/>\n',
    encoding="utf-8")
for act in pathlib.Path("android/app/src/main").rglob("MainActivity.kt"):
    pkg = re.search(r"^package\s+(\S+)", act.read_text(encoding="utf-8"), re.M).group(1)
    act.write_text(f"""package {pkg}

import android.app.NotificationChannel
import android.app.NotificationManager
import android.media.AudioAttributes
import android.net.Uri
import android.os.Build
import android.os.Bundle
import io.flutter.embedding.android.FlutterActivity

class MainActivity : FlutterActivity() {{
    override fun onCreate(savedInstanceState: Bundle?) {{
        super.onCreate(savedInstanceState)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {{
            val nm = getSystemService(NotificationManager::class.java)
            if (nm.getNotificationChannel("sos_siren") == null) {{
                val ch = NotificationChannel("sos_siren", "Alertes SOS", NotificationManager.IMPORTANCE_HIGH)
                ch.description = "Sirène des alertes SOS AMANE"
                ch.enableVibration(true)
                ch.vibrationPattern = longArrayOf(0, 800, 400, 800, 400, 800)
                ch.setSound(
                    Uri.parse("android.resource://" + packageName + "/raw/siren"),
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_ALARM)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build()
                )
                nm.createNotificationChannel(ch)
            }}
        }}
    }}
}}
""", encoding="utf-8")
    print("MainActivity patched:", act)

print("Android files patched")
print(open("android/app/build.gradle.kts" if pathlib.Path("android/app/build.gradle.kts").exists() else "android/app/build.gradle").read())
